def pluck(arr):
    min_even = None
    min_index = -1

    for index, value in enumerate(arr):
        if value % 2 == 0:
            if min_even is None or value < min_even:
                min_even = value
                min_index = index

    return [min_even, min_index] if min_even is not None else []
